/* Public layout only: never stores or displays private account data before auth. */
window.MioRouteShell=(()=>{
 const host=document.getElementById('routeLoading');let failed=false;
 const labels={dashboard:'Dashboard',profile:'My profile',wallet:'My Wallet',deposit:'Deposit',withdraw:'Withdraw','top-up':'Top Up',exchange:'Exchange Wallet',transfer:'Transfer MIO',transactions:'Transaction history',network:'My network','network-graphical':'Graphical Network',earnings:'Earnings',ecommerce:'E-commerce',orders:'My orders',packages:'Subscription Plans',security:'Account security',login:'Sign in',join:'Join free',support:'Account support',product:'Product',order:'Order',vendors:'Vendors',categories:'Categories',vendor:'Store',category:'Category'};
 const adminLabels={home:'Admin Dashboard','network-home':'Network Controls','ecommerce-home':'E-commerce Controls','package-report':'Package Activation Report',members:'All Account Holders & Members',plans:'Edit Plans',premium:'Platinum payments','bonus-wallets':'Bonus Wallet Settings','monthly-maintenance':'Monthly Maintenance','binary-pool':'Binary Share Pool','company-earnings':'Company Earnings','company-account':'Company Account','company-leftover':'Company Leftover','company-held':'Company Held Amount',system:'Transaction history',storefront:'Shopfront & notices',vendors:'Seller requests',brands:'Stores & brands','seller-registration':'Sell with us',products:'Product listings',orders:'Orders & payments','manager-program':'Manager & Leadership','super-member':'Super Member','community-share':'Global Community Share',ecommerce:'E-commerce Report',commissions:'Sales allocation history',withdrawals:'Seller withdrawals',network:'Network trees',settings:'Marketplace settings',wallet:'Company MIO Wallet',support:'Account support'};
 function render(){if(!host||!document.documentElement.classList.contains('route-restoring'))return;const parts=location.hash.slice(1).split('?')[0].split('/'),admin=['workspace','admin'].includes(parts[0]),title=(admin?adminLabels[parts[1]||'home']:labels[parts[0]])||'Account';const links=admin?['Network Controls','Package Activation Report','All Account Holders & Members','Edit Plans','Platinum payments','Bonus Wallet Settings','Monthly Maintenance','Binary Share Pool']:['Dashboard','My profile','My network','Earnings','Wallet','My Wallet','Transfer MIO','Transaction history','My orders'];const columns=parts[1]==='package-report'?['Date','Member','Package','Payment','Status']:parts[1]==='members'?['Name','MIO ID','Sponsor','Package','Status']:['Date & time','Details','Amount','Status'];document.querySelector('header.top')?.after(host);host.innerHTML=`<aside class="route-shell-sidebar" aria-hidden="true"><small>${admin?'NETWORK CONTROL CENTRE':'MEMBER WORKSPACE'}</small><strong>${admin?'Admin Dashboard':'Account centre'}</strong>${links.map(t=>`<span class="${t===title?'selected':''}">${t}</span>`).join('')}</aside><section class="route-shell-body"><header><h1>${title}</h1><span class="route-shell-status" role="status">${failed?'Connection interrupted':'Refreshing…'}</span></header>${failed?'<p>Could not refresh this page. Please try again.</p><button type="button" class="btn" data-route-retry>Retry</button>':`<div class="route-shell-content" aria-hidden="true"><div class="route-shell-filters"><i></i><i></i><i></i></div><div class="route-shell-table"><div class="route-shell-columns">${columns.map(c=>`<span>${c}</span>`).join('')}</div>${[1,2,3,4,5].map(()=>'<div class="route-shell-row"><i></i><i></i><i></i></div>').join('')}</div></div>`}</section>`;host.querySelector('[data-route-retry]')?.addEventListener('click',()=>location.reload())}
 function finish(){document.documentElement.classList.remove('route-restoring');host?.replaceChildren()}
 function fail(){failed=true;document.documentElement.classList.add('route-restoring');render()}
 render();window.addEventListener('hashchange',render);return{finish,fail};
})();
